import numpy as np
from PIL import Image
import random

img = Image.open('chart.jpg')
arr = np.array(img)
height, width, _ = arr.shape

# collect pixels of group 3 (hue around 0.983)
import colorsys
samples = []
for y in range(height):
    for x in range(width):
        r,g,b = arr[y, x]
        if r > 240 and g > 240 and b > 240:
            continue
        if r < 50 and g < 50 and b < 50:
            continue
        h,s,v = colorsys.rgb_to_hsv(r/255., g/255., b/255.)
        if 0.9 < h < 1.0:
            samples.append((x,y,r,g,b))
            if len(samples) > 10:
                break
    if len(samples) > 10:
        break

print("Group 3 sample colors (RGB):")
for x,y,r,g,b in samples:
    print(f"({r},{g},{b}) at ({x},{y})")
    # also check if near legend area (x > 800 maybe)
    if x > 800:
        print("  likely legend")
